import{_ as t,c as s,o as l,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"易附錄纂注","description":"易附錄纂注 - 易附錄纂注","frontmatter":{"title":"易附錄纂注","description":"易附錄纂注 - 易附錄纂注"},"headers":[],"relativePath":"classics/yifulu-zuanzhu/001.md","filePath":"classics/yifulu-zuanzhu/001.md"}'),r={name:"classics/yifulu-zuanzhu/001.md"};function i(c,a,o,u,p,d){return l(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"易附錄纂注",tabindex:"-1"},[n("易附錄纂注 "),e("a",{class:"header-anchor",href:"#易附錄纂注","aria-label":"Permalink to “易附錄纂注”"},"​")],-1),e("p",null,"欽定四庫全書經部一",-1),e("p",null,"易類提要",-1),e("p",null,"臣 等謹案：",-1),e("p",null,"易附錄纂注十五卷，元胡一桂撰。一桂字庭芳，號雙湖，婺源人。景定甲子領鄉薦，試禮部不第，教授鄉里以終。事蹟具元史儒學傳。是編以朱子本義為宗，取文集、語錄之及於易者附之，謂之「附錄」；取諸儒易說之合於本義者纂之，謂之「纂注」。其去取別裁，惟以朱子為斷。元史稱其受易源流出於朱子，殆以啟蒙翼傳及是書歟？陳櫟稱一桂此書於楊萬里易傳無半字及之。今檢其所引櫟說，信然。蓋宋末元初，講學者門戶最嚴，而新安諸儒於授受源流辨別尤甚。萬里易傳雖遠宗程子，而早工吟詠，與范成大、陸游齊名，不甚以講學為事。故雖嘗薦朱子，拒韓侂冑，而慶元黨禁獨不列名，一桂蓋以詞人擯之，未必盡以其書也。乾隆四十六年十月恭校上。",-1),e("p",null,"總纂官 臣 紀昀、 臣 陸錫熊、 臣 孫士毅，總校官 臣 陸費墀。",-1)])])}const _=t(r,[["render",i]]);export{m as __pageData,_ as default};
